import{_ as t,c as r,o as i,a2 as o}from"./chunks/framework.CIiVzG-O.js";const c=JSON.parse('{"title":"简介","description":"","frontmatter":{},"headers":[],"relativePath":"zh-CN/guide/introduction.md","filePath":"zh-CN/guide/introduction.md","lastUpdated":1793163976000}'),n={name:"zh-CN/guide/introduction.md"};function l(e,a,s,h,g,d){return i(),r("div",null,[...a[0]||(a[0]=[o('<h1 id="简介" tabindex="-1">简介 <a class="header-anchor" href="#简介" aria-label="Permalink to &quot;简介&quot;">​</a></h1><h2 id="关于-nuezip" tabindex="-1">关于 NueZip <a class="header-anchor" href="#关于-nuezip" aria-label="Permalink to &quot;关于 NueZip&quot;">​</a></h2><p>NueZip 是一款为 macOS 打造的专业归档管理器，主打速度、可靠性和易用性。无论是压缩文件、解压归档、转换格式，还是管理加密归档，NueZip 都能以原生的 macOS 体验为你妥善处理。</p><p>NueZip 基于 Swift 6 和 SwiftUI 构建，充分利用 Apple Silicon 与 macOS 技术，提供一款快速、轻量且安全的归档管理工具。</p><h2 id="核心功能" tabindex="-1">核心功能 <a class="header-anchor" href="#核心功能" aria-label="Permalink to &quot;核心功能&quot;">​</a></h2><h3 id="📦-多格式支持" tabindex="-1">📦 <strong>多格式支持</strong> <a class="header-anchor" href="#📦-多格式支持" aria-label="Permalink to &quot;📦 **多格式支持**&quot;">​</a></h3><p>NueZip 支持所有主流归档格式：</p><ul><li><strong>RAR</strong> — 只读，支持多卷</li><li><strong>ZIP</strong> — 通用压缩，支持 AES 加密</li><li><strong>7-Zip</strong> — 高压缩比，采用 LZMA2</li><li><strong>TAR</strong> — 归档打包，可选 GZIP/BZIP2</li><li><strong>GZIP / BZIP2</strong> — 独立的压缩格式</li></ul><h3 id="⚡-快速解压" tabindex="-1">⚡ <strong>快速解压</strong> <a class="header-anchor" href="#⚡-快速解压" aria-label="Permalink to &quot;⚡ **快速解压**&quot;">​</a></h3><p>双引擎架构会为每种格式选择最优的后端，确保尽可能快的解压速度。</p><h3 id="🔐-密码保护与加密" tabindex="-1">🔐 <strong>密码保护与加密</strong> <a class="header-anchor" href="#🔐-密码保护与加密" aria-label="Permalink to &quot;🔐 **密码保护与加密**&quot;">​</a></h3><p>使用行业标准加密创建带密码保护的归档。内置密码管理器将凭据安全地存储在你本地的钥匙串中。</p><h3 id="📋-批量操作" tabindex="-1">📋 <strong>批量操作</strong> <a class="header-anchor" href="#📋-批量操作" aria-label="Permalink to &quot;📋 **批量操作**&quot;">​</a></h3><p>一次性处理多个文件：</p><ul><li><strong>批量压缩</strong> — 将多个项目分别压缩为独立的归档</li><li><strong>批量解压</strong> — 同时解压多个归档</li><li><strong>批量转换</strong> — 批量在格式之间转换归档</li><li><strong>批量加密</strong> — 为多个归档应用密码保护</li></ul><h3 id="🛠️-高级工具" tabindex="-1">🛠️ <strong>高级工具</strong> <a class="header-anchor" href="#🛠️-高级工具" aria-label="Permalink to &quot;🛠️ **高级工具**&quot;">​</a></h3><ul><li><strong>归档修复</strong> — 修复损坏的 RAR 和 ZIP 归档</li><li><strong>格式转换</strong> — 在任意支持的格式之间转换</li><li><strong>性能基准测试</strong> — 测试压缩速度与评级</li><li><strong>归档搜索</strong> — 按名称在归档中查找文件</li><li><strong>文件信息查看器</strong> — 查看归档条目的详细元数据</li><li><strong>分卷/拆分支持</strong> — 创建多卷归档</li></ul><h3 id="🖥️-原生-macos-体验" tabindex="-1">🖥️ <strong>原生 macOS 体验</strong> <a class="header-anchor" href="#🖥️-原生-macos-体验" aria-label="Permalink to &quot;🖥️ **原生 macOS 体验**&quot;">​</a></h3><ul><li><strong>Swift 6 + SwiftUI</strong> — 现代、响应式的界面</li><li><strong>Apple Silicon 原生</strong> — 针对 M 系列芯片优化</li><li><strong>Finder 集成</strong> — 右键上下文菜单扩展</li><li><strong>拖放</strong> — 通过菜单栏放置面板快速访问</li><li><strong>极低的资源占用</strong> — 轻量的后台运行</li></ul><h2 id="系统要求" tabindex="-1">系统要求 <a class="header-anchor" href="#系统要求" aria-label="Permalink to &quot;系统要求&quot;">​</a></h2><ul><li><strong>操作系统</strong>：macOS 14 Sonoma 或更高版本</li><li><strong>CPU</strong>：Apple Silicon（M 系列）或 Intel（64 位）</li><li><strong>内存</strong>：最低 4GB，推荐 8GB</li><li><strong>存储空间</strong>：安装约需 50 MB</li></ul><h2 id="支持的语言" tabindex="-1">支持的语言 <a class="header-anchor" href="#支持的语言" aria-label="Permalink to &quot;支持的语言&quot;">​</a></h2><p>NueZip 支持英语、简体中文、繁体中文、日语、韩语以及许多其他语言。</p><h2 id="开始使用" tabindex="-1">开始使用 <a class="header-anchor" href="#开始使用" aria-label="Permalink to &quot;开始使用&quot;">​</a></h2><p>如果你是 NueZip 的新用户，请从 <a href="/zh-CN/guide/installation.html">安装指南</a> 开始，在你的 Mac 上运行该应用。</p>',25)])])}const p=t(n,[["render",l]]);export{c as __pageData,p as default};
